/* Compare Excel TT sheet CCCD vs HRS_Employee EmployeeCode (EmployeeStatusID=1) */
var fs = require('fs');
var path = require('path');
var XLSX = require('xlsx');

var root = path.join(__dirname, '..');
var excelPath = path.join(root, 'Import_Can_Bo_Nganh - QCET.xlsx');
var sqlPath = path.join(root, 'sql', 'nhân sự', 'data', 'HRS_Employee.sql');
var outDir = path.join(root, '0Docss');
var outHtml = path.join(outDir, 'thong-ke-so-sanh-cccd-hrs-employee.html');

function normalizeCode(v) {
  if (v === null || v === undefined) {
    return '';
  }
  var s = String(v).trim();
  if (/^\d+\.?\d*$/.test(s)) {
    s = String(Math.round(parseFloat(s)));
  }
  return s.replace(/\s+/g, '');
}

function normalizeName(s) {
  if (!s) {
    return '';
  }
  return String(s)
    .trim()
    .replace(/\s+/g, ' ')
    .toLowerCase()
    .normalize('NFC');
}

function parseDobFromExcel(v) {
  if (v === null || v === undefined || v === '') {
    return null;
  }
  if (typeof v === 'number' && v > 1000) {
    var dc = XLSX.SSF.parse_date_code(v);
    if (dc) {
      return { d: dc.d, m: dc.m, y: dc.y };
    }
  }
  var s = String(v).trim();
  var m = s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);
  if (m) {
    return { d: parseInt(m[1], 10), m: parseInt(m[2], 10), y: parseInt(m[3], 10) };
  }
  return null;
}

function dobKey(dob) {
  if (!dob) {
    return '';
  }
  return dob.y + '-' + dob.m + '-' + dob.d;
}

function formatDob(dob) {
  if (!dob) {
    return '';
  }
  var dd = dob.d < 10 ? '0' + dob.d : String(dob.d);
  var mm = dob.m < 10 ? '0' + dob.m : String(dob.m);
  return dd + '/' + mm + '/' + dob.y;
}

function parseSqlValues(valuesPart) {
  var tokens = [];
  var i = 0;
  var cur = '';
  var inStr = false;
  var strQuote = '';
  while (i < valuesPart.length) {
    var ch = valuesPart.charAt(i);
    if (inStr) {
      if (ch === "'") {
        if (valuesPart.charAt(i + 1) === "'") {
          cur += "'";
          i += 2;
          continue;
        }
        inStr = false;
        i++;
        continue;
      }
      cur += ch;
      i++;
      continue;
    }
    if (ch === "N" && valuesPart.charAt(i + 1) === "'") {
      inStr = true;
      strQuote = 'N';
      i += 2;
      continue;
    }
    if (ch === "'") {
      inStr = true;
      strQuote = "'";
      i++;
      continue;
    }
    if (ch === ',') {
      tokens.push(cur.trim());
      cur = '';
      i++;
      continue;
    }
    cur += ch;
    i++;
  }
  if (cur.length) {
    tokens.push(cur.trim());
  }
  return tokens;
}

function loadEmployeesFromSql() {
  var text = fs.readFileSync(sqlPath, 'utf8');
  var lines = text.split(/\r?\n/);
  var headerLine = null;
  var cols = [];
  var employees = [];
  var idx = {};

  for (var li = 0; li < lines.length; li++) {
    var line = lines[li];
    if (line.indexOf('INSERT [dbo].[HRS_Employee]') === -1) {
      continue;
    }
    if (!headerLine) {
      headerLine = line;
      var start = line.indexOf('[EmployeeID]');
      var end = line.indexOf(') VALUES');
      var part = line.substring(start, end);
      cols = part.split('], [').map(function (s) {
        return s.replace(/^\[/, '').replace(/\]$/, '');
      });
      idx.employeeId = cols.indexOf('EmployeeID');
      idx.employeeCode = cols.indexOf('EmployeeCode');
      idx.firstName = cols.indexOf('FirstName');
      idx.lastName = cols.indexOf('LastName');
      idx.fullname = cols.indexOf('Fullname');
      idx.birthDay = cols.indexOf('BirthDay');
      idx.birthMonth = cols.indexOf('BirthMonth');
      idx.birthYear = cols.indexOf('BirthYear');
      idx.employeeStatusId = cols.indexOf('EmployeeStatusID');
      idx.isDeleted = cols.indexOf('IsDeleted');
    }
    var vp = line.indexOf('VALUES (');
    if (vp < 0) {
      continue;
    }
    var valuesPart = line.substring(vp + 'VALUES ('.length, line.lastIndexOf(')'));
    var tokens = parseSqlValues(valuesPart);
    if (tokens.length !== cols.length) {
      continue;
    }
    var employeeId = parseInt(tokens[idx.employeeId], 10);
    var statusId = parseInt(tokens[idx.employeeStatusId], 10);
    var isDeleted = tokens[idx.isDeleted] === '1';
    if (employeeId === 0 || statusId !== 1 || isDeleted) {
      continue;
    }
    var bd = tokens[idx.birthDay] === 'NULL' ? null : parseInt(tokens[idx.birthDay], 10);
    var bm = tokens[idx.birthMonth] === 'NULL' ? null : parseInt(tokens[idx.birthMonth], 10);
    var by = tokens[idx.birthYear] === 'NULL' ? null : parseInt(tokens[idx.birthYear], 10);
    var dob = bd && bm && by ? { d: bd, m: bm, y: by } : null;
    var fn = tokens[idx.fullname];
    if (fn.indexOf('N\'') === 0) {
      fn = fn.substring(2, fn.length - 1);
    } else if (fn.charAt(0) === "'") {
      fn = fn.substring(1, fn.length - 1);
    }
    var code = tokens[idx.employeeCode];
    if (code.indexOf('N\'') === 0) {
      code = code.substring(2, code.length - 1);
    } else if (code.charAt(0) === "'") {
      code = code.substring(1, code.length - 1);
    }
    employees.push({
      employeeId: employeeId,
      employeeCode: normalizeCode(code),
      fullname: fn,
      nameKey: normalizeName(fn),
      dob: dob,
      dobKey: dobKey(dob),
      dobText: formatDob(dob)
    });
  }
  return employees;
}

function loadExcelRows() {
  var wb = XLSX.readFile(excelPath);
  var ws = wb.Sheets['TT'];
  var rows = XLSX.utils.sheet_to_json(ws, { header: 1, defval: '' });
  var result = [];
  for (var r = 2; r < rows.length; r++) {
    var row = rows[r];
    if (!row || !row.length) {
      continue;
    }
    var stt = String(row[0] || '').trim();
    if (stt === 'Mẫu' || stt === 'Mau') {
      continue;
    }
    var ho = String(row[1] || '').trim();
    var ten = String(row[2] || '').trim();
    var cccd = normalizeCode(row[4]);
    if (!cccd && !ho && !ten) {
      continue;
    }
    var dob = parseDobFromExcel(row[3]);
    var fullname = (ho + ' ' + ten).replace(/\s+/g, ' ').trim();
    result.push({
      rowNum: r + 1,
      stt: stt,
      ho: ho,
      ten: ten,
      fullname: fullname,
      nameKey: normalizeName(fullname),
      cccd: cccd,
      maCanBo: normalizeCode(row[5]),
      trangThai: String(row[21] || '').trim(),
      dob: dob,
      dobKey: dobKey(dob),
      dobText: formatDob(dob)
    });
  }
  return result;
}

function escHtml(s) {
  return String(s || '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

function tableHtml(id, title, headers, rows) {
  var h = '<section id="' + id + '"><h2>' + escHtml(title) + ' <span class="badge">' + rows.length + '</span></h2>';
  if (!rows.length) {
    return h + '<p class="empty">Không có bản ghi.</p></section>';
  }
  h += '<div class="table-wrap"><table><thead><tr>';
  for (var i = 0; i < headers.length; i++) {
    h += '<th>' + escHtml(headers[i]) + '</th>';
  }
  h += '</tr></thead><tbody>';
  for (var ri = 0; ri < rows.length; ri++) {
    h += '<tr>';
    for (var ci = 0; ci < rows[ri].length; ci++) {
      h += '<td>' + escHtml(rows[ri][ci]) + '</td>';
    }
    h += '</tr>';
  }
  h += '</tbody></table></div></section>';
  return h;
}

var dbList = loadEmployeesFromSql();
var excelList = loadExcelRows();

var dbByCode = {};
var excelByCode = {};
var dbByPerson = {};
var excelByPerson = {};

for (var i = 0; i < dbList.length; i++) {
  var e = dbList[i];
  if (e.employeeCode) {
    if (!dbByCode[e.employeeCode]) {
      dbByCode[e.employeeCode] = [];
    }
    dbByCode[e.employeeCode].push(e);
  }
  if (e.nameKey && e.dobKey) {
    var pk = e.nameKey + '|' + e.dobKey;
    if (!dbByPerson[pk]) {
      dbByPerson[pk] = [];
    }
    dbByPerson[pk].push(e);
  }
}

for (var j = 0; j < excelList.length; j++) {
  var x = excelList[j];
  if (x.cccd) {
    if (!excelByCode[x.cccd]) {
      excelByCode[x.cccd] = [];
    }
    excelByCode[x.cccd].push(x);
  }
  if (x.nameKey && x.dobKey) {
    var pk2 = x.nameKey + '|' + x.dobKey;
    if (!excelByPerson[pk2]) {
      excelByPerson[pk2] = [];
    }
    excelByPerson[pk2].push(x);
  }
}

var matchedFull = [];
var excelMissingInDb = [];
var dbMissingInExcel = [];
var samePersonDiffCode = [];
var sameCodeDiffPerson = [];
var sameCodePartialMatch = [];

for (var k = 0; k < excelList.length; k++) {
  var ex = excelList[k];
  if (!ex.cccd) {
    excelMissingInDb.push([ex.stt, ex.fullname, ex.dobText, '(trống CCCD)', ex.trangThai, 'Excel thiếu mã CCCD']);
    continue;
  }
  var dbHits = dbByCode[ex.cccd] || [];
  if (!dbHits.length) {
    excelMissingInDb.push([ex.stt, ex.fullname, ex.dobText, ex.cccd, ex.maCanBo, ex.trangThai]);
    continue;
  }
  var db0 = dbHits[0];
  var nameOk = ex.nameKey === db0.nameKey;
  var dobOk = ex.dobKey === db0.dobKey;
  if (nameOk && dobOk) {
    matchedFull.push([ex.stt, ex.fullname, ex.dobText, ex.cccd, db0.employeeId, db0.fullname, db0.dobText]);
  } else if (!nameOk && !dobOk) {
    sameCodeDiffPerson.push([
      ex.cccd,
      'Excel: ' + ex.fullname + ' | ' + ex.dobText,
      'DB: ' + db0.fullname + ' | ' + db0.dobText,
      db0.employeeId
    ]);
  } else {
    sameCodePartialMatch.push([
      ex.cccd,
      ex.fullname,
      ex.dobText,
      db0.fullname,
      db0.dobText,
      nameOk ? 'OK' : 'Lệch họ tên',
      dobOk ? 'OK' : 'Lệch ngày sinh',
      db0.employeeId
    ]);
  }
}

for (var d = 0; d < dbList.length; d++) {
  var emp = dbList[d];
  if (!emp.employeeCode) {
    continue;
  }
  if (!excelByCode[emp.employeeCode]) {
    dbMissingInExcel.push([emp.employeeId, emp.employeeCode, emp.fullname, emp.dobText]);
  }
}

var personKeys = {};
for (var pk in excelByPerson) {
  if (excelByPerson.hasOwnProperty(pk)) {
    personKeys[pk] = true;
  }
}
for (var pk3 in dbByPerson) {
  if (dbByPerson.hasOwnProperty(pk3)) {
    personKeys[pk3] = true;
  }
}

for (var personKey in personKeys) {
  if (!personKeys.hasOwnProperty(personKey)) {
    continue;
  }
  var exRows = excelByPerson[personKey] || [];
  var dbRows = dbByPerson[personKey] || [];
  if (!exRows.length || !dbRows.length) {
    continue;
  }
  var exCodes = {};
  var dbCodes = {};
  for (var a = 0; a < exRows.length; a++) {
    if (exRows[a].cccd) {
      exCodes[exRows[a].cccd] = true;
    }
  }
  for (var b = 0; b < dbRows.length; b++) {
    dbCodes[dbRows[b].employeeCode] = true;
  }
  var exCodeList = Object.keys(exCodes);
  var dbCodeList = Object.keys(dbCodes);
  var overlap = false;
  for (var c = 0; c < exCodeList.length; c++) {
    if (dbCodes[exCodeList[c]]) {
      overlap = true;
      break;
    }
  }
  if (overlap) {
    continue;
  }
  samePersonDiffCode.push([
    exRows[0].fullname,
    exRows[0].dobText,
    exCodeList.join(', '),
    dbCodeList.join(', '),
    exRows[0].stt,
    dbRows.map(function (r) {
      return r.employeeId;
    }).join(', ')
  ]);
}

var excelWithCccd = 0;
for (var w = 0; w < excelList.length; w++) {
  if (excelList[w].cccd) {
    excelWithCccd++;
  }
}

var stats = {
  dbStatus1: dbList.length,
  excelTotal: excelList.length,
  excelWithCccd: excelWithCccd,
  matchedFull: matchedFull.length,
  excelNotInDb: excelMissingInDb.length,
  dbNotInExcel: dbMissingInExcel.length,
  samePersonDiffCode: samePersonDiffCode.length,
  sameCodeDiffPerson: sameCodeDiffPerson.length,
  sameCodePartial: sameCodePartialMatch.length
};

if (!fs.existsSync(outDir)) {
  fs.mkdirSync(outDir, { recursive: true });
}

var html = '<!DOCTYPE html><html lang="vi"><head><meta charset="utf-8"/><meta name="viewport" content="width=device-width,initial-scale=1"/>';
html += '<title>So sánh CCCD Excel vs HRS_Employee (Status=1)</title>';
html += '<style>';
html += 'body{font-family:Segoe UI,Tahoma,sans-serif;margin:0;background:#f4f6f8;color:#1a1a1a;}';
html += 'header{background:#1e3a5f;color:#fff;padding:20px 24px;} header h1{margin:0 0 8px;font-size:22px;} header p{margin:4px 0;opacity:.9;font-size:14px;}';
html += 'nav{background:#fff;border-bottom:1px solid #ddd;padding:10px 24px;position:sticky;top:0;z-index:2;} nav a{margin-right:14px;color:#1e3a5f;text-decoration:none;font-size:13px;}';
html += '.wrap{padding:20px 24px 40px;} .cards{display:grid;grid-template-columns:repeat(auto-fill,minmax(180px,1fr));gap:12px;margin-bottom:24px;}';
html += '.card{background:#fff;border:1px solid #e0e4ea;border-radius:8px;padding:14px;} .card .n{font-size:26px;font-weight:700;color:#1e3a5f;} .card .l{font-size:12px;color:#555;margin-top:4px;}';
html += 'section{background:#fff;border:1px solid #e0e4ea;border-radius:8px;padding:16px;margin-bottom:20px;} section h2{margin:0 0 12px;font-size:17px;}';
html += '.badge{background:#1e3a5f;color:#fff;border-radius:999px;padding:2px 8px;font-size:12px;margin-left:6px;}';
html += '.table-wrap{overflow:auto;max-height:520px;border:1px solid #eee;border-radius:6px;} table{border-collapse:collapse;width:100%;font-size:13px;}';
html += 'th,td{border-bottom:1px solid #eee;padding:8px 10px;text-align:left;vertical-align:top;} th{background:#f0f3f7;position:sticky;top:0;} tr:nth-child(even){background:#fafbfc;}';
html += '.empty{color:#666;font-style:italic;} .note{font-size:13px;color:#444;line-height:1.5;}';
html += '</style></head><body>';
