function parseSqlValues(valuesPart) {
  var tokens = [];
  var i = 0;
  var cur = '';
  var inStr = false;
  while (i < valuesPart.length) {
    var ch = valuesPart.charAt(i);
    if (inStr) {
      if (ch === "'") {
        if (valuesPart.charAt(i + 1) === "'") {
          cur += "'";
          i += 2;
          continue;
        }
        inStr = false;
        i++;
        continue;
      }
      cur += ch;
      i++;
      continue;
    }
    if (ch === 'N' && valuesPart.charAt(i + 1) === "'") {
      inStr = true;
      i += 2;
      continue;
    }
    if (ch === "'") {
      inStr = true;
      i++;
      continue;
    }
    if (ch === ',') {
      tokens.push(cur.trim());
      cur = '';
      i++;
      continue;
    }
    cur += ch;
    i++;
  }
  if (cur.length) {
    tokens.push(cur.trim());
  }
  return tokens;
}

